package com.aiorigin.detector

/** Strength of the metadata signal. None of these levels is cryptographic proof. */
enum class OriginLevel {
    /** C2PA or IPTC metadata declares the content was generated by a trained model. */
    AI_DECLARED,
    /** Metadata declares the content was edited/composited with a trained model. */
    AI_EDITED,
    /** A generation tool name or generation settings (A1111/ComfyUI) are embedded. */
    AI_TOOL,
    /** A prompt-like field exists, but no tool or declaration. */
    PROMPT,
    /** Only a generic description/comment exists. */
    DESCRIPTION,
    UNKNOWN
}

/** Metadata is user-editable; none of these outcomes authenticate AI origin. */
data class MetadataAssessment(
    val status: String,
    val promptKey: String?,
    val rawPrompt: String?,
    val indicators: List<String>,
    val level: OriginLevel = OriginLevel.UNKNOWN,
    val tool: String? = null,
    val software: String? = null,
    val c2paPresent: Boolean = false,
    val c2paGenerator: String? = null,
    val generationSettings: Boolean = false
)

object MetadataAssessor {
    /** Specific enough to search in every metadata value. */
    private val generationTools = listOf(
        "comfyui", "automatic1111", "stable diffusion", "stable-diffusion", "sdxl", "fooocus", "invokeai",
        "novelai", "midjourney", "dall-e", "dall·e", "gpt-image", "leonardo.ai", "ideogram", "diffusionbee",
        "draw things"
    )
    /** Ambiguous words: only trusted inside software / generator / creator-tool fields. */
    private val softwareOnlyTools = listOf(
        "chatgpt", "openai", "firefly", "imagen", "gemini", "flux", "bing image creator", "microsoft designer",
        "meta ai", "grok", "kling", "runway", "sora", "veo", "pika", "luma"
    )
    private const val MAX_TOOL_SEARCH = 200_000
    private val wordPatterns = HashMap<String, Regex>()
    /** "luma" must not match "LumaFusion", nor "imagen" "Imagenomic"; a version may follow ("SDXL1.0"). */
    private fun wholeWord(name: String): Regex = synchronized(wordPatterns) {
        wordPatterns.getOrPut(name) {
            Regex("(?<![\\p{L}\\p{N}])" + Regex.escape(name) + "(?!\\p{L})", RegexOption.IGNORE_CASE)
        }
    }
    private val softwareKeyParts = listOf("software", "c2pa.generator", "creatortool", "processingsoftware")
    private val explicitPromptKeys = listOf("positive_prompt", "positive prompt", "parameters", "generation_data", "prompt", "negative_prompt", "negative prompt")
    private val weakKeys = setOf("description", "comment", "imagedescription", "usercomment")
    private val declaredGenerated = Regex("(?<!compositewith)trainedalgorithmicmedia", RegexOption.IGNORE_CASE)
    private val declaredEdited = Regex("compositewithtrainedalgorithmicmedia", RegexOption.IGNORE_CASE)

    /** ComfyUI stores its node graph as JSON without naming itself; recognise the node structure. */
    private val comfyNodes = listOf("\"KSampler", "\"CLIPTextEncode\"", "\"CheckpointLoaderSimple\"", "\"VAEDecode\"", "\"SamplerCustom")
    private fun isComfyGraph(value: String): Boolean {
        val trimmed = value.trimStart()
        if (!(trimmed.startsWith("{") || trimmed.startsWith("["))) return false
        val head = value.take(500_000)
        return head.contains("\"class_type\"") && comfyNodes.any { head.contains(it) } ||
            head.contains("\"nodes\"") && head.contains("\"links\"") && comfyNodes.any { head.contains(it) }
    }

    /** First generic description/comment, for display only — never presented as a prompt. */
    fun description(metadata: Map<String, String>): String? = metadata.entries.firstOrNull { (key, value) ->
        weakKeys.any { key.lowercase().contains(it) } && value.isNotBlank() && !value.trimStart().startsWith("{") &&
            GenerationParametersParser.parse(value) == null
    }?.value?.trim()?.take(2_000)

    fun assess(metadata: Map<String, String>): MetadataAssessment {
        val indicators = mutableListOf<String>()
        val software = metadata.entries.firstOrNull { it.key.contains("software", true) }?.value
        val softwareValues = metadata.entries.filter { (k, _) -> softwareKeyParts.any { k.contains(it, true) } }.map { it.value }
        // Raw XMP packets carry base64 thumbnails and unrelated namespaces; their fields are
        // searched after extraction instead, so random text cannot produce a tool match.
        val searchable = metadata.values.filterNot { XmpFields.looksLikeXmp(it) }
        val tool = searchable.firstNotNullOfOrNull { value ->
            generationTools.firstOrNull { wholeWord(it).containsMatchIn(value.take(MAX_TOOL_SEARCH)) }
        } ?: softwareValues.firstNotNullOfOrNull { value ->
            softwareOnlyTools.firstOrNull { wholeWord(it).containsMatchIn(value.take(MAX_TOOL_SEARCH)) }
        } ?: if (metadata.values.any(::isComfyGraph)) "ComfyUI" else null
        val c2paPresent = metadata["c2pa.present"] == "true"
        val c2paGenerator = metadata["c2pa.generator"]
        val generated = metadata.values.any { declaredGenerated.containsMatchIn(it) }
        val edited = !generated && metadata.values.any { declaredEdited.containsMatchIn(it) }
        val settings = metadata.values.any { it.length <= 200_000 && GenerationParametersParser.parse(it) != null }

        if (generated) indicators.add("Metadata declares trained-algorithmic (AI) media")
        if (edited) indicators.add("Metadata declares AI-assisted editing")
        if (c2paPresent) indicators.add("C2PA manifest present (signature not verified)")
        if (c2paGenerator != null) indicators.add("C2PA generator: ${c2paGenerator.take(120)}")
        if (tool != null) indicators.add("Generation-tool string in editable metadata: $tool")
        if (settings) indicators.add("A1111-style generation settings in metadata")
        if (software != null) indicators.add("Software field: ${software.take(120)}")
        // Prefer positive/generation fields over negative-only data regardless of file field order.
        // A negative prompt alone is never a positive generation prompt.
        val explicit = explicitPromptKeys.firstNotNullOfOrNull { wanted ->
            metadata.entries.firstOrNull { (key, value) ->
                key.trim().equals(wanted, ignoreCase = true) && value.isNotBlank()
            }
        }
        val parameterEntry = if (explicit == null && settings)
            metadata.entries.firstOrNull { GenerationParametersParser.parse(it.value) != null } else null
        val weak = metadata.entries.firstOrNull { (key, value) ->
            weakKeys.any { key.lowercase().contains(it) } && value.isNotBlank()
        }
        val selected = explicit ?: parameterEntry ?: weak
        val level = when {
            generated -> OriginLevel.AI_DECLARED
            edited -> OriginLevel.AI_EDITED
            tool != null || settings -> OriginLevel.AI_TOOL
            explicit != null -> OriginLevel.PROMPT
            weak != null -> OriginLevel.DESCRIPTION
            else -> OriginLevel.UNKNOWN
        }
        val status = when (level) {
            OriginLevel.AI_DECLARED -> "AI generation declared in metadata (unverified)"
            OriginLevel.AI_EDITED -> "AI editing declared in metadata (unverified)"
            OriginLevel.AI_TOOL -> "AI creation metadata found (unverified)"
            OriginLevel.PROMPT -> "Prompt-like metadata found (unverified)"
            OriginLevel.DESCRIPTION -> "Description found; origin unknown"
            OriginLevel.UNKNOWN -> "Origin unknown"
        }
        return MetadataAssessment(
            status, selected?.key, selected?.value, indicators, level, tool, software,
            c2paPresent, c2paGenerator, settings
        )
    }
}
